#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Apply INT-09 to the composite request batch and emit the audit deliverables."""
import csv
import json
import os

AUDIT_DATE = "2026-03-31"
INPUT_DIR = "/app/input"
OUT_DIR = "/app"

# Canonical finding order (matches the policy's "Finding names" section).
FINDING_ORDER = [
    "UNLICENSED_CHARACTER_USE",
    "THIRD_PARTY_BACKGROUND_UNLICENSED",
    "MISSING_MINOR_CONSENT",
    "COMMERCIAL_DISTRIBUTION_FLAG",
    "ALTERATION_DISCLOSURE_MISSING",
]

PUBLIC_PAID = {"social_public", "print_for_sale"}


def load_csv(path):
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def parse_list(val):
    """Parse a ';'-joined list field. 'none' or '' -> empty set."""
    if val is None or val.strip() == "" or val.strip() == "none":
        return set()
    return set(p.strip() for p in val.split(";") if p.strip())


def date_ge(a, b):
    """True if date string a is on or after date string b (ISO dates compare lexically)."""
    return a >= b


# --- Load data ---------------------------------------------------------------
accounts_raw = load_csv(os.path.join(INPUT_DIR, "client_accounts.csv"))
licences_raw = load_csv(os.path.join(INPUT_DIR, "licensed_property_register.csv"))
log_raw = load_csv(os.path.join(INPUT_DIR, "composite_request_log.csv"))

accounts = {a["account_id"]: a for a in accounts_raw}

# --- Build effective licence terms, applying supersession (§2) --------------
# A row that supersedes another governs every request citing EITHER id.
licences_by_id = {l["license_id"]: l for l in licences_raw}

effective = {}  # license_id -> effective dict {license_type, covers, valid_until, gov_id}
for l in licences_raw:
    effective[l["license_id"]] = {
        "license_type": l["license_type"],
        "covers": parse_list(l["covers_distribution"]),
        "valid_until": l["valid_until"],
        "gov_id": l["license_id"],
    }

# Apply supersession: for each superseding row, point the superseded id at the
# superseding row's terms.
for l in licences_raw:
    sup = l["supersedes"]
    if sup and sup != "none":
        # The superseded id is governed by this superseding row's terms.
        effective[sup] = {
            "license_type": l["license_type"],
            "covers": parse_list(l["covers_distribution"]),
            "valid_until": l["valid_until"],
            "gov_id": l["license_id"],
        }


def licence_covers(license_id_on_row, need_type, distribution):
    """§2: does a licence of need_type cover this request's distribution?"""
    if license_id_on_row == "none" or license_id_on_row == "":
        return (False, None)
    eff = effective.get(license_id_on_row)
    if eff is None:
        return (False, None)  # id not in register
    if eff["license_type"] != need_type:
        return (False, eff["gov_id"])
    if distribution not in eff["covers"] and "all" not in eff["covers"]:
        return (False, eff["gov_id"])
    if not date_ge(eff["valid_until"], AUDIT_DATE):
        return (False, eff["gov_id"])
    return (True, eff["gov_id"])


# --- Per-request audit (§3-§7) over audited (non-withdrawn) requests ---------
audit_rows = []
findings_by_req = {}

for r in log_raw:
    rid = r["request_id"]
    if r["intake_status"] == "withdrawn":
        continue  # §1: withdrawn requests are not audited, count toward nothing

    dist = r["intended_distribution"]
    account = accounts[r["account_id"]]
    acc_covers = parse_list(account["master_agreement_covers"])
    acc_active = account["agreement_status"] == "active"

    fset = set()

    # §3 Licensed-character use
    if r["character_property"] != "none":
        cleared = False
        # personal-use allowance
        if dist == "personal_only":
            cleared = True
        # character licence
        if not cleared:
            cov, _ = licence_covers(r["character_license_id"], "character", dist)
            if cov:
                cleared = True
        if not cleared:
            fset.add("UNLICENSED_CHARACTER_USE")

    # §4 Third-party backgrounds
    bs = r["background_source"]
    if bs == "third_party_unlicensed":
        fset.add("THIRD_PARTY_BACKGROUND_UNLICENSED")  # do not look up the id
    elif bs == "third_party_licensed":
        cov, _ = licence_covers(r["background_license_id"], "background", dist)
        if not cov:
            fset.add("THIRD_PARTY_BACKGROUND_UNLICENSED")
    # customer_original -> never a finding

    # §5 Minor consent
    if r["subject_is_minor"] == "True":
        ctype = r["minor_consent_type"]
        valid = r["minor_consent_valid_until"]
        ok = True
        if ctype == "none" or ctype == "":
            ok = False  # not present
        elif not date_ge(valid, AUDIT_DATE):
            ok = False  # not current
        else:
            # wide enough?
            if ctype == "basic":
                if dist not in ("personal_only", "client_internal"):
                    ok = False
            # publicity covers every distribution
        if not ok:
            fset.add("MISSING_MINOR_CONSENT")

    # §6 Commercial distribution routing
    if dist in PUBLIC_PAID:
        cleared = acc_active and dist in acc_covers
        if not cleared:
            fset.add("COMMERCIAL_DISTRIBUTION_FLAG")

    # §7 Alteration disclosure
    if r["alteration_level"] == "substantive" and dist in PUBLIC_PAID:
        if r["alteration_disclosure_on_file"] != "True":
            fset.add("ALTERATION_DISCLOSURE_MISSING")

    findings_by_req[rid] = fset
    ordered = [c for c in FINDING_ORDER if c in fset]
    finding_str = "|".join(ordered) if ordered else "none"
    audit_rows.append((rid, finding_str, ordered))

# --- §8 Account escalation ---------------------------------------------------
# Batch-wide share = audited requests carrying >=1 finding / audited requests.
audited_reqs = [r for r in log_raw if r["intake_status"] != "withdrawn"]
n_audited = len(audited_reqs)
n_flagged = sum(1 for rid, s, o in audit_rows if o)
batch_share = n_flagged / n_audited

# Group audited requests by account.
reqs_by_account = {}
for r in audited_reqs:
    reqs_by_account.setdefault(r["account_id"], []).append(r["request_id"])

account_rows = []
escalated = []
for aid, acc in accounts.items():
    rids = reqs_by_account.get(aid, [])
    cnt = len(rids)
    flagged = sum(1 for rid in rids if findings_by_req[rid])
    share = flagged / cnt if cnt else 0.0
    max_findings = max((len(findings_by_req[rid]) for rid in rids), default=0)
    escalate = False
    reason = ""
    if share > batch_share:
        escalate = True
        reason = "share"
    elif max_findings >= 3:
        escalate = True
        reason = "triple"
    if escalate:
        escalated.append(aid)
    esc_str = "ESCALATION_REQUIRED" if escalate else "none"
    account_rows.append((aid, acc["account_type"], cnt, flagged, esc_str, reason, share, max_findings))

# --- Write composite_request_audit.csv --------------------------------------
audit_csv_path = os.path.join(OUT_DIR, "composite_request_audit.csv")
with open(audit_csv_path, "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    w.writerow(["request_id", "finding"])
    for rid, s, o in audit_rows:
        w.writerow([rid, s])

# --- Write account_summary.csv ----------------------------------------------
account_csv_path = os.path.join(OUT_DIR, "account_summary.csv")
with open(account_csv_path, "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    w.writerow(["account_id", "account_type", "request_count", "flagged_requests", "escalation"])
    for aid, atype, cnt, flagged, esc_str, reason, share, mx in account_rows:
        w.writerow([aid, atype, cnt, flagged, esc_str])

# --- Write results.json ------------------------------------------------------
def count_finding(code):
    return sum(1 for rid, s, o in audit_rows if code in o)

results = {
    "request_count": n_audited,
    "account_count": len(reqs_by_account),
    "flagged_count": n_flagged,
    "compliant_count": n_audited - n_flagged,
    "finding_total": sum(len(o) for rid, s, o in audit_rows),
    "character_count": count_finding("UNLICENSED_CHARACTER_USE"),
    "background_count": count_finding("THIRD_PARTY_BACKGROUND_UNLICENSED"),
    "consent_count": count_finding("MISSING_MINOR_CONSENT"),
    "commercial_count": count_finding("COMMERCIAL_DISTRIBUTION_FLAG"),
    "disclosure_count": count_finding("ALTERATION_DISCLOSURE_MISSING"),
    "escalated_accounts": len(escalated),
}
with open(os.path.join(OUT_DIR, "results.json"), "w", encoding="utf-8") as f:
    json.dump(results, f, indent=2)
    f.write("\n")

# --- Verification / diagnostics ----------------------------------------------
print("AUDIT DATE:", AUDIT_DATE)
print("Audited requests:", n_audited)
print("Withdrawn (excluded):", [r["request_id"] for r in log_raw if r["intake_status"] == "withdrawn"])
print("Flagged requests:", n_flagged, " Compliant:", n_audited - n_flagged)
print("Finding total:", sum(len(o) for rid, s, o in audit_rows))
print("Batch share: {}/{} = {:.6f}".format(n_flagged, n_audited, batch_share))
print()
print("Per-request findings:")
for rid, s, o in audit_rows:
    print("  ", rid, "->", s)
print()
print("Per-account:")
for aid, atype, cnt, flagged, esc_str, reason, share, mx in account_rows:
    print(f"  {aid} {atype} cnt={cnt} flagged={flagged} share={share:.4f} max={mx} {esc_str} ({reason})")
print()
print("Escalated accounts:", escalated, "count=", len(escalated))
print()
print("Finding-type counts:")
for c in FINDING_ORDER:
    print("  ", c, "=", count_finding(c))
print()
print("Effective licence terms:")
for lid in sorted(effective.keys()):
    e = effective[lid]
    gov = "" if e["gov_id"] == lid else f" (gov by {e['gov_id']})"
    print(f"  {lid}: {e['license_type']} covers={sorted(e['covers'])} valid={e['valid_until']}{gov}")
print()
print("results.json:", json.dumps(results))

